 static void check(boolean ok,String reason){count++;if(!ok)throw new AssertionError(reason);}
 static void near(double a,double b,String reason){check(Double.isFinite(a)&&Math.abs(a-b)<Math.max(1e-7,Math.abs(b)*1e-9),reason+": "+a);}
 interface Work{void run()throws Exception;}static void rejects(Work work,String reason)throws Exception{boolean rejected=false;try{work.run();}catch(Exception e){rejected=true;}check(rejected,reason);}
 static String text(String name)throws Exception{return new String(bytes(name),"UTF-8");}static byte[] bytes(String name)throws Exception{return Files.readAllBytes(files.resolve(name));}
 public static void main(String[] args)throws Exception{
  files=Paths.get(args[0]);String master=text("sedemac-holdings.json");JSONObject filing=Parse.latest(master,"SEDEMAC",false);Data.Ownership now=Parse.ownership(bytes("sedemac-0.xml"),filing);near(now.promoter,26.23,"SEDEMAC promoter ownership matches filing/screenshot");near(now.publicPct,73.77,"SEDEMAC public ownership matches filing/screenshot");near(now.mutual,20.57,"SEDEMAC MF ownership matches screenshot");near(now.fundCount,23,"Reported holder count is retained");near(now.foreign,10.30,"Foreign portfolio categories aggregated without named-holder duplication");near(now.pledged,0,"Explicit no-pledge disclosure becomes zero");check(now.holders.size()==6,"Six named filing groups, not 23 schemes");Data.Holder sbi=now.holders.stream().filter(h->h.name.startsWith("SBI Innovative")).findFirst().get();near(sbi.percent,4.33,"SBI 4.33% belongs to one combined filing row");near(sbi.shares,1913615,"SBI combined shares match source");check(sbi.name.contains("SBI Balanced Hybrid Fund"),"All grouped names retained");check(now.holders.size()!=now.fundCount,"Named rows are not equated with reported holder count");JSONObject prior=Comparisons.filing(master,"SEDEMAC",false,now.date,"",false);check(Parse.canonical(Parse.str(prior,"date")).equals("2026-06-30"),"Previous ownership period chosen");Data.Ownership before=Parse.ownership(bytes("sedemac-1.xml"),prior);near(Research.percentagePoints(now.foreign,before.foreign),6.03,"FPI change is percentage points, not percent return");check(Comparisons.filing(master,"SEDEMAC",false,"2026-03-09","",false)==null,"No fabricated previous period");Data.Ownership empty=Parse.ownership("<root/>".getBytes("UTF-8"),filing);check(Double.isNaN(empty.mutual)&&Double.isNaN(empty.foreign)&&Double.isNaN(empty.pledged),"Missing ownership fields do not become zero");
  String mixed="<x:xbrl xmlns:x='http://www.xbrl.org/2003/instance' xmlns:s='urn:test'><x:context id='old'><x:period><x:instant>2026-06-30</x:instant></x:period></x:context><x:context id='current'><x:period><x:instant>2026-09-30</x:instant></x:period></x:context><s:WhetherAnySharesHeldByPromotersAreEncumberedUnderPledgedForPromoterAndPromoterGroup contextRef='old'>false</s:WhetherAnySharesHeldByPromotersAreEncumberedUnderPledgedForPromoterAndPromoterGroup><s:WhetherAnySharesHeldByPromotersAreEncumberedUnderPledgedForPromoterAndPromoterGroup contextRef='current'>true</s:WhetherAnySharesHeldByPromotersAreEncumberedUnderPledgedForPromoterAndPromoterGroup></x:xbrl>";check(Double.isNaN(Parse.ownership(mixed.getBytes("UTF-8"),filing).pledged),"Historical no-pledge flag cannot become a current zero");
  Data.Financial current=new Data.Financial(),previous=new Data.Financial();current.basis=previous.basis="Consolidated";current.start="2026-07-01";current.end="2026-09-30";previous.start="2026-04-01";previous.end="2026-06-30";check(Comparisons.fits(current,previous),"Comparable quarters allowed");previous.start="2026-01-01";check(!Comparisons.fits(current,previous),"Half-year and quarter cannot be compared");previous.start="2026-04-01";previous.basis="Standalone";check(!Comparisons.fits(current,previous),"Consolidated/standalone cannot mix");previous.basis="Consolidated";previous.revenueLabel="Total income";check(!Comparisons.fits(current,previous),"Different income definitions cannot mix");near(Research.change(120,100),20,"Positive-base growth");check(Double.isNaN(Research.change(20,0))&&Double.isNaN(Research.change(20,-10)),"Growth from non-positive base unavailable");
  Research.Feed<Research.Ipo> currentIssues=Research.issues(text("ipo-current.json"),"current"),past=Research.issues(text("ipo-past.json"),"past"),upcoming=Research.issues(text("ipo-upcoming-real.json"),"upcoming");check(currentIssues.rows.size()==1,"Current NSE issue list parsed");check(upcoming.rows.isEmpty(),"Legitimate empty upcoming feed accepted");Research.Ipo vpfl=currentIssues.rows.get(0);check(vpfl.symbol.equals("VPFL"),"IPO issuer matched");check(vpfl.phase(LocalDate.of(2026,11,5)).equals("Closed"),"Current feed does not imply IPO is open");check(vpfl.phase(LocalDate.of(2026,11,3)).equals("Open by dates"),"Open phase follows published dates");check(vpfl.phase(LocalDate.of(2026,11,1)).equals("Upcoming"),"Future phase from dates");near(vpfl.subscription,1.85,"Reported total subscription retained");List<Research.Ipo> merged=Research.merge(Arrays.asList(currentIssues,past));check(merged.size()==past.rows.size(),"IPO identities deduplicate across feeds");Research.Ipo combined=merged.stream().filter(i->i.symbol.equals("VPFL")).findFirst().get();near(combined.high,94,"Past price band enriches current record");near(combined.subscription,1.85,"Merge preserves current subscription");check(combined.start.equals("2026-11-02")&&combined.end.equals("2026-11-04"),"Date normalization preserves issue identity");Research.Ipo bcss=merged.stream().filter(i->i.symbol.equals("BCSSL")).findFirst().get();check(bcss.phase(LocalDate.of(2026,11,5)).equals("Listed"),"Listing phase uses published listing date");rejects(()->Research.issues("{}","current"),"Malformed issue feed rejected");check(currentIssues.stamp.isEmpty(),"No synthetic exchange timestamp");
  Research.IssueInfo info=Research.issueInfo(text("ipo-detail.json"),"VPFL");near(info.lot,1200,"Lot shares from exact source field");near(info.low,88,"Lower band");near(info.high,94,"Upper band");near(Research.lotCost(info.high,info.lot,1),112800,"One-lot amount does not claim minimum application");near(Research.lotCost(info.high,info.lot,2),225600,"Two-lot calculator");check(Double.isNaN(Research.lotCost(94,1200,1.5)),"Fractional lots rejected");check(Double.isNaN(Research.lotCost(0,1200,2)),"Missing/zero issue price rejected");check(info.bids.size()==4,"Only parent bid categories plus total displayed");check(info.bids.stream().noneMatch(r->r[0].equals("Foreign Institutional Investors(FIIs)")),"Child category not double-counted");rejects(()->Research.issueInfo(text("ipo-detail.json"),"TCS"),"Wrong issuer detail rejected");near(Research.band("Rs.1,250 to Rs.1,350")[1],1350,"Comma-separated upper band");
  Research.Feed<Research.Gmp> gain=Research.gmp(text("investorgain.html"),"InvestorGain"),watch=Research.gmp(text("ipowatch.html"),"IPOWatch");check(gain.rows.size()>10&&watch.rows.size()>=6,"Both original publisher tables parse");check(gain.stamp.startsWith("2026-11-05"),"Publisher page modification time retained");Research.Gmp antala=gain.rows.stream().filter(q->q.name.equals("Antala Industries")).findFirst().get();check(Double.isNaN(antala.premium),"Publisher -- GMP stays unavailable, not zero");check(Double.isNaN(antala.estimated()),"No listing-price illustration with unavailable GMP");Research.Gmp antalaWatch=watch.rows.stream().filter(q->q.name.equals("Antala Industries")).findFirst().get();near(antalaWatch.premium,0,"Explicit publisher zero is valid");check(antalaWatch.dates.equals("29-5 Nov"),"Publisher period text retained without invented dates");Research.Gmp vedant=gain.rows.stream().filter(q->q.name.equals("Vedant Poly Fabs")).findFirst().get();near(vedant.premium,1,"GMP is current premium, not daily high/low");near(vedant.price,94,"Publisher price retained separately");near(vedant.estimated(),95,"Price-plus-premium illustration");near(vedant.percent(),100d/94,"Premium percent uses matching publisher price");check(vedant.stamp.equals("5-Nov 7:02"),"Row timestamp preserved without invented year");Research.Gmp bombay=gain.rows.stream().filter(q->q.name.startsWith("Bombay Coated")).findFirst().get(),bombayWatch=watch.rows.stream().filter(q->q.name.startsWith("Bombay Coated")).findFirst().get();check(bombay.premium!=bombayWatch.premium,"Publisher disagreement retained, never averaged");check(!bombay.id().equals(bombayWatch.id()),"Histories remain publisher-specific");check(Research.href("<a href='https://evil.example/x'>x</a>","https://ipowatch.in").isEmpty(),"Off-provider links cannot become source reports");check(Research.clean("<script>wrong=999</script>ABC &amp; Co &#8377;1").equals("ABC & Co ₹1"),"HTML is reduced to source text; no scripts");rejects(()->Research.gmp("<html>Challenge page</html>","InvestorGain"),"Blocked/changed publisher page is not empty success");
  InvestorState state=new InvestorState("{}");Research.Position position=new Research.Position();position.symbol="SEDEMAC";position.name="SEDEMAC Mechatronics";position.quantity=10;position.average=3000;position.fees=50;state.position(position);near(position.cost(),30050,"Manual cost includes fees");near(position.value(3130),31300,"Valuation uses quantity and source price");near(position.pnl(3130),1250,"Unrealized P&L pairs matching cost/valuation");check(Double.isNaN(position.pnl(Double.NaN)),"Unpriced position never becomes zero valuation");position.quantity=-1;rejects(()->state.position(position),"Short/negative quantity cannot enter long-equity ledger");position.quantity=1.5;rejects(()->state.position(position),"Fractional shares rejected for this ledger");position.quantity=10;state.note("SEDEMAC","Thesis and risks");check(state.note("SEDEMAC").equals("Thesis and risks"),"Research note saved locally");InvestorState round=new InvestorState(state.toString());near(round.positions().get(0).cost(),30050,"Position JSON round trip");check(round.note("SEDEMAC").equals("Thesis and risks"),"Note round trip");
  state.alert("SEDEMAC",2900,3200);check(state.check("SEDEMAC",3300,"05-Nov-2026 10:00",false).isEmpty(),"Saved quote cannot trigger a new threshold event");check(state.check("SEDEMAC",3300,"05-Nov-2026 10:00",true).size()==1,"Fresh qualifying quote triggers once");check(state.check("SEDEMAC",3310,"05-Nov-2026 10:01",true).isEmpty(),"Repeated above-threshold quotes do not spam");state.check("SEDEMAC",3100,"05-Nov-2026 10:02",true);check(state.check("SEDEMAC",3200,"05-Nov-2026 10:03",true).size()==1,"Threshold re-arms after condition clears");check(state.check("SEDEMAC",2900,"05-Nov-2026 10:04",true).size()==1,"At-or-below threshold inclusive");check(state.check("SEDEMAC",2800,"",true).isEmpty(),"Undated quote cannot trigger");rejects(()->state.alert("SEDEMAC",3300,3200),"Inverted thresholds rejected");rejects(()->state.alert("SEDEMAC",Double.NaN,Double.NaN),"Empty thresholds rejected");check(state.alertLog().size()==3,"Only source-backed threshold events retained");
  state.track(vpfl,true);check(state.tracked(vpfl.id()),"IPO tracking persists original issue identity");check(new InvestorState(state.toString()).tracked().get(0).start.equals("2026-11-02"),"Tracked issue dates survive export");state.track(vpfl,false);check(!state.tracked(vpfl.id()),"IPO can be untracked without external changes");state.observe(vedant,gain.stamp,1);state.observe(vedant,gain.stamp,2);check(state.history(vedant).length()==1,"Unchanged publisher quote is not duplicate history");double original=vedant.premium;vedant.premium=2;state.observe(vedant,gain.stamp,3);check(state.history(vedant).length()==2,"Changed GMP is a new observed snapshot");for(int n=0;n<40;n++){vedant.premium=n;state.observe(vedant,gain.stamp,n+10);}check(state.history(vedant).length()==30,"Observed history bounded");vedant.premium=original;state.removePosition("SEDEMAC");check(state.positions().isEmpty(),"Removing local record is independent of any order");
  List<Research.Event> actions=Research.events(text("tcs-actions.json"),true,"TCS");check(actions.size()==1&&actions.get(0).title.contains("Rs 12"),"Original corporate action extracted");check(actions.get(0).date.equals("14-Oct-2026"),"Original ex-date retained");check(Research.events(text("tcs-actions.json"),true,"SEDEMAC").isEmpty(),"Events cannot leak from another stock");check(Net.allowed(Research.GAIN)&&Net.allowed(Research.WATCH),"Only approved publisher hosts added");check(!Net.allowed("https://www.investorgain.com.evil.example/x"),"Publisher host lookalike rejected");
  System.out.println("Passed "+count+" investor/holdings/IPO/GMP checks.");
 }
